CREATE TABLE IF NOT EXISTS user_sessions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,session_hash CHAR(64) NOT NULL UNIQUE,ip_address VARCHAR(45),user_agent VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,last_seen_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,revoked_at TIMESTAMP NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX idx_sessions_user(user_id,revoked_at));
CREATE TABLE IF NOT EXISTS password_reset_tokens (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,expires_at TIMESTAMP NOT NULL,used_at TIMESTAMP NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS security_rate_limits (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,scope_key VARCHAR(191) NOT NULL,action VARCHAR(80) NOT NULL,window_started_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,attempts INT UNSIGNED NOT NULL DEFAULT 0,UNIQUE KEY uq_rate(scope_key,action));
